use vstd::prelude::*;

verus! {

fn hstack(a: Vec<f32>, b: Vec<f32>) -> (res: Vec<f32>)
    ensures
        res@.len() == a@.len() + b@.len(),
        forall|i: int| 0 <= i < a@.len() ==> res@[i] == a@[i],
        forall|j: int| 0 <= j < b@.len() ==> res@[a@.len() + j] == b@[j],
{
    let mut res: Vec<f32> = Vec::new();

    // Copy a
    let mut i: usize = 0;
    while i < a.len()
        invariant
            0 <= i <= a@.len(),
            res@.len() == i as int,
            forall|k: int| 0 <= k < i as int ==> res@[k] == a@[k],
        decreases (a.len() - i),
    {
        res.push(a[i]);
        i += 1;
    }

    // Copy b
    let mut j: usize = 0;
    while j < b.len()
        invariant
            0 <= j <= b@.len(),
            res@.len() == a@.len() + j as int,
            // a-part preserved
            forall|k: int| 0 <= k < a@.len() ==> res@[k] == a@[k],
            // b-part copied so far
            forall|k: int| 0 <= k < j as int ==> res@[a@.len() + k] == b@[k],
        decreases (b.len() - j),
    {
        res.push(b[j]);
        j += 1;
    }

    res
}

} // verus!

